// FR-N4: report the failure to a visible channel (container log) and sign it for Convex.
const crypto = require('crypto');
const d = $input.first().json;
const report = {
  workflow: String((d.workflow && d.workflow.name) || 'unknown workflow').slice(0, 200),
  executionId: String((d.execution && d.execution.id) || (d.trigger && 'trigger-' + Date.now()) || 'unknown').slice(0, 100),
  node: String((d.execution && d.execution.lastNodeExecuted) || (d.trigger && d.trigger.error && d.trigger.error.node && d.trigger.error.node.name) || 'unknown node').slice(0, 200),
  message: String(((d.execution && d.execution.error) || (d.trigger && d.trigger.error) || {}).message || 'no message').slice(0, 500),
};
console.error(`[lendloop] workflow failed: ${report.workflow} > ${report.node}: ${report.message}`);
const secret = $env.LENDLOOP_CONVEX_HMAC_SECRET;
const body = JSON.stringify(report);
const ts = String(Math.floor(Date.now() / 1000));
const signature = crypto.createHmac('sha256', secret).update(`${ts}.${body}`).digest('hex');
return [{ json: { body, ts, eventId: `n8n_${crypto.randomUUID()}`, signature } }];
